            publishHTML([reportDir: 'coverage', reportFiles: 'index.html'])
        }
        failure {
            slackSend(color: 'danger', message: "Pipeline failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}")
        }
    }
}
```

**Handling Secrets in CI:**

Never hardcode secrets. Use your CI's secret management:

```javascript
// In tests
const api = axios.create({
  baseURL: process.env.API_URL,
  headers: { Authorization: `Bearer ${process.env.TEST_TOKEN}` }
});

// In CI configuration
# GitHub Actions
env:
  TEST_TOKEN: ${{ secrets.TEST_TOKEN }}

# Jenkins
withCredentials([string(credentialsId: 'test-token', variable: 'TEST_TOKEN')])
```

**Test Results and Reporting:**

Make test results visible and actionable:

```javascript
// Generate JUnit XML for CI integration
const reporter = new JUnitReporter({
  outputDir: './test-results',
  outputFile: 'results.xml'
});

// Generate HTML report for humans
const htmlReporter = new HTMLReporter({
  outputDir: './reports',
  template: 'custom-template.html'
});

// Post results to Slack/Discord
if (process.env.CI) {
  const webhook = process.env.SLACK_WEBHOOK;
  await postResultsToSlack(webhook, results);
}
```

**Key Insight:** CI integration turns tests from something you run occasionally into something that protects your codebase continuously. Make them fast, make them reliable, and make their results visible.

Flaky tests are tests that sometimes pass and sometimes fail without any code changes. They're the enemy of automation—they destroy trust and waste time.

**The Cost of Flaky Tests:**

When tests are flaky, developers learn to ignore failures. They assume "it's probably just a flaky test" and merge anyway. Then real bugs slip through. Flaky tests are worse than no tests at all.

**Common Causes of Flakiness:**

| Cause | Description | Solution |
|-------|-------------|----------|
| **Timing issues** | Test expects response faster than possible | Add retries, increase timeouts |
| **Data conflicts** | Tests interfere with each other's data | Isolate test data |
| **Order dependency** | Tests assume a specific run order | Make tests independent |
| **Environment differences** | Works locally, fails in CI | Match environments |
| **Race conditions** | Actual race condition in code | Fix the code |
| **External services** | Third-party API down | Mock or use test doubles |

**Detecting Flaky Tests:**

The first step is identifying which tests are flaky:

```javascript
// flaky-detector.js
class FlakyDetector {
  constructor(testFile) {
    this.testFile = testFile;
    this.results = [];
  }

  async runTest(iterations = 10) {
    for (let i = 0; i < iterations; i++) {
      const start = Date.now();
      try {
        // Run the test in a isolated process
        const result = await runTestIsolated(this.testFile);
        this.results.push({
          iteration: i,
          passed: true,
          duration: Date.now() - start
        });
      } catch (error) {
        this.results.push({
          iteration: i,
          passed: false,
          duration: Date.now() - start,
          error: error.message
        });
      }
    }

    return this.analyze();
  }

  analyze() {
    const passes = this.results.filter(r => r.passed).length;
    const flaky = passes > 0 && passes < this.results.length;

    return {
      total: this.results.length,
      passes,
      failures: this.results.length - passes,
      flaky,
      consistency: (passes / this.results.length) * 100
    };
  }
}

// Usage
const detector = new FlakyDetector('tests/users.test.js');
const result = await detector.runTest(20);
if (result.flaky) {
  console.log(`Test is flaky: ${result.consistency}% pass rate`);
}
```

**Strategies for Dealing with Flakiness:**

**1. Fix the root cause (best)**

If the test is flaky because of a race condition in your code, fix the code.

**2. Increase timeouts**

```javascript
// Before (flaky when slow)
test('returns data quickly', async () => {
  const response = await api.get('/slow-endpoint');
  expect(response.status).toBe(200);
});

// After (more patient)
test('returns data', async () => {
  const response = await api.get('/slow-endpoint', { timeout: 10000 });
  expect(response.status).toBe(200);
});
```

**3. Retry flaky tests**

```javascript
// jest.config.js
module.exports = {
  // Retry a test up to 2 times if it fails
  retryTimes: 2,

  // Only retry specific tests
  retry: {
    patterns: ['flaky', 'slow']
  }
};

// Or per-test
jest.retryTimes(3);
test('potentially flaky test', async () => {
  // ...
});
```

**4. Isolate test data**

```javascript
// Before - tests interfere with each other
let sharedUser;

test('creates user', async () => {
  sharedUser = await createUser();
  expect(sharedUser).toBeDefined();
});

test('updates user', async () => {
  // Depends on previous test
  const response = await updateUser(sharedUser.id);
  expect(response.status).toBe(200);
});

// After - each test creates its own data
test('creates user', async () => {
  const user = await createUser();
  expect(user).toBeDefined();
});

test('updates user', async () => {
  const user = await createUser();
  const response = await updateUser(user.id);
  expect(response.status).toBe(200);
});
```

**5. Mock external dependencies**

```javascript
// Before - calls real payment API (unreliable)
test('processes payment', async () => {
  const response = await api.post('/payments', { amount: 100 });
  expect(response.status).toBe(200);
});

// After - mock the payment service
jest.mock('../../services/payment-service');

test('processes payment', async () => {
  PaymentService.process.mockResolvedValue({ id: 123, status: 'success' });

  const response = await api.post('/payments', { amount: 100 });
  expect(response.status).toBe(200);
});
```

**6. Quarantine flaky tests**

When you can't fix them immediately, quarantine them:

```javascript
// flaky-tests.js
const isQuarantineMode = process.env.QUARANTINE === 'true';

const testFn = isQuarantineMode ? test.skip : test;

testFn('flaky test that needs fixing', async () => {
  // ...
});
```

**Key Insight:** Never ignore flaky tests. Either fix them or remove them. A suite with flaky tests is worse than no suite at all.

Tests aren't write-once-run-forever. They need maintenance as your API evolves. A good test suite is a living thing that grows and changes with your codebase.

**The Test Maintenance Cycle:**

```
┌─────────────────────────────────────────────────────────────────┐
│                    TEST MAINTENANCE CYCLE                         │
├─────────────────────────────────────────────────────────────────┤
│                                                                   │
│  1. Write test → 2. Run test → 3. Test passes                     │
│         ↑                            │                            │
│         │                            ▼                            │
│         │                    4. API changes                       │
│         │                            │                            │
│         │                            ▼                            │
│         │                    5. Test fails                        │
│         │                            │                            │
│         └────────────────────────────┘                            │
│                    6. Update test                                 │
│                                                                   │
└─────────────────────────────────────────────────────────────────┘
```

**When Tests Need Maintenance:**

- **API changes** - New fields, removed fields, changed behavior
- **Bug fixes** - Tests that expected wrong behavior need updating
- **Performance improvements** - Timeout thresholds may change
- **Refactoring** - Test structure can be improved
- **Flakiness** - Tests that are unreliable need attention

**Signs Your Tests Need Love:**

1. **They take too long** - >10 minutes is too slow
2. **They fail often** - >1% flakiness is too high
3. **They're hard to understand** - New team members struggle
4. **They duplicate code** - Copy-paste everywhere
5. **They test the wrong things** - Implementation details instead of behavior

**Refactoring Tests:**

Just like production code, tests benefit from refactoring:

```javascript
// Before - duplicated code everywhere
test('creates user', async () => {
  const response = await axios.post('https://api.example.com/users', {
    name: 'John',
    email: 'john@example.com'
  });
  expect(response.status).toBe(201);
});

test('updates user', async () => {
  const response = await axios.patch('https://api.example.com/users/123', {
    name: 'John Updated'
  });
  expect(response.status).toBe(200);
});

// After - extracted client and helpers
const api = new ApiClient('https://api.example.com');

test('creates user', async () => {
  const response = await api.users.create(UserFactory.create());
  expect(response.status).toBe(201);
});

test('updates user', async () => {
  const response = await api.users.update(123, { name: 'John Updated' });
  expect(response.status).toBe(200);
});
```

**Removing Obsolete Tests:**

It's okay to delete tests that are no longer valuable:

- Tests for removed features
- Tests that never fail (over-testing)
- Tests that duplicate other tests
- Tests that are more trouble than they're worth

**Regular Test Reviews:**

Schedule regular test health reviews:

```javascript
// test-review.js
class TestHealthReview {
  constructor() {
    this.metrics = {
      totalTests: 0,
      passRate: 0,
      averageDuration: 0,
      flakyCount: 0,
      coverage: 0
    };
  }

  async runReview() {
    await this.collectMetrics();
    await this.identifyProblemTests();
    await this.generateRecommendations();
    await this.sendReport();
  }

  async collectMetrics() {
    // Run tests and collect stats
    const results = await runTests();
    this.metrics.totalTests = results.total;
    this.metrics.passRate = results.passed / results.total * 100;
    this.metrics.averageDuration = results.totalDuration / results.total;
    this.metrics.flakyCount = results.flaky.length;
    this.metrics.coverage = await getCoverage();
  }

  async identifyProblemTests() {
    // Find slow tests
    const slow = await findSlowTests({ threshold: 2000 });

    // Find flaky tests
    const flaky = await findFlakyTests({ runs: 10 });

    // Find tests with low coverage
    const lowCoverage = await findLowCoverageTests();

    return { slow, flaky, lowCoverage };
  }

  generateRecommendations() {
    const recs = [];

    if (this.metrics.passRate < 95) {
      recs.push('Pass rate below 95% - investigate failures');
    }

    if (this.metrics.averageDuration > 1000) {
      recs.push('Tests are slow - consider parallelization');
    }

    if (this.metrics.flakyCount > 5) {
      recs.push(`${this.metrics.flakyCount} flaky tests - quarantine or fix`);
    }

    return recs;
  }
}
```

**Key Insight:** Tests are code. Treat them with the same respect as production code—review them, refactor them, and keep them healthy.

Beyond basic organization, collections offer powerful features for complex API workflows.

**Collection Variables:**

Define variables at the collection level:

```json
{
  "baseUrl": "https://api.example.com/v1",
  "apiVersion": "2025-04-01",
  "timeout": 5000,
  "defaultHeaders": {
    "Content-Type": "application/json",
    "Accept": "application/json"
  }
}
```

Usage in requests:
- URL: `{{baseUrl}}/users`
- Headers: `X-API-Version: {{apiVersion}}`

**Collection-Level Scripts:**

Scripts that run for every request in the collection:

```javascript
// Pre-request Script (runs before each request)
// Add timestamp to avoid caching
pm.variables.set("timestamp", Date.now());

// Log request details for debugging
console.log(`Making ${pm.request.method} request to ${pm.request.url}`);

// Test Script (runs after each request)
// Ensure all responses are JSON
pm.test("Response is JSON", () => {
  pm.response.to.have.header("Content-Type", "application/json");
});

// Track response times
pm.test("Response time is acceptable", () => {
  pm.expect(pm.response.responseTime).to.be.below(1000);
});
```

**Folder-Level Scripts:**

Scripts that only run for requests in a specific folder:

```javascript
// Folder: Authenticated Requests
// Pre-request Script
const token = pm.environment.get("authToken");
if (!token) {
  console.error("No auth token found. Run Login request first.");
  throw new Error("Authentication required");
}

// Add auth header to all requests in this folder
pm.request.headers.add({
  key: "Authorization",
  value: `Bearer ${token}`
});
```

**Request Chaining:**

Connect requests by passing data between them:

```javascript
// In POST Create User request (Tests tab)
pm.test("User created successfully", () => {
  const response = pm.response.json();

  // Save user ID for subsequent requests
  pm.collectionVariables.set("newUserId", response.id);
  pm.environment.set("lastCreatedUserId", response.id);

  // Log for debugging
  console.log(`Created user with ID: ${response.id}`);
});

// In GET User request, use the saved ID
// URL: {{baseUrl}}/users/{{newUserId}}
```

**Collection Run Order:**

Control the execution order:

```javascript
// In pre-request or test scripts
// Skip to next request
postman.setNextRequest("Get User Profile");

// Jump to specific folder/request
postman.setNextRequest("Authentication/Refresh Token");

// Stop collection run
postman.setNextRequest(null);
```

**Data-Driven Testing with Collections:**

Use CSV or JSON files to run the same request with different data:

```csv
# users.csv
name,email,age
John,john@test.com,30
Jane,jane@test.com,25
Bob,bob@test.com,35
```

```json
// users.json
[
  { "name": "John", "email": "john@test.com", "age": 30 },
  { "name": "Jane", "email": "jane@test.com", "age": 25 },
  { "name": "Bob", "email": "bob@test.com", "age": 35 }
]
```

In your request:
```javascript
// Use variables from data file
{
  "name": "{{name}}",
  "email": "{{email}}",
  "age": {{age}}
}
```

**Collection Hooks:**

Execute scripts at specific points:

| Hook | Timing | Use Case |
|------|--------|----------|
| **prerequest** | Before each request | Setup, authentication |
| **test** | After each request | Validation, data extraction |
| **folder:prerequest** | Before folder requests | Folder-specific setup |
| **folder:test** | After folder requests | Folder-specific validation |
| **collection:prerequest** | Before collection runs | Global setup |
| **collection:test** | After collection runs | Global cleanup |

**Collection Templates:**

Postman provides templates for common API patterns:

1. **REST API Basics** - Standard CRUD operations
2. **Authentication Flows** - OAuth 2.0, JWT, API Key
3. **GraphQL** - Queries and mutations
4. **SOAP** - XML-based APIs
5. **File Upload** - Multipart form data

**Key Insight:** Collections are programmable. Use scripts, variables, and flow control to create sophisticated API workflows that go far beyond simple request/response.

Variables are placeholders for dynamic values. They make your collections reusable across different environments and scenarios.

**Variable Scopes:**

Postman has a hierarchy of variable scopes:

```
┌─────────────────────────────────────────────────────────────────┐
│                    VARIABLE SCOPE HIERARCHY                        │
├─────────────────────────────────────────────────────────────────┤
│                                                                   │
│  Global (Lowest priority)                                        │
│  └── Collection                                                  │
│       └── Environment                                            │
│            └── Data (from data files)                            │
│                 └── Local (Highest priority)                     │
│                                                                   │
│  When resolving a variable, Postman uses the most specific       │
│  (highest priority) value available.                             │
│                                                                   │
└─────────────────────────────────────────────────────────────────┘
```

**Variable Scopes Explained:**

| Scope | Lifetime | Access | Use Case |
|-------|----------|--------|----------|
| **Global** | Until manually cleared | `pm.globals` | Values that rarely change |
| **Collection** | With collection | `pm.collectionVariables` | Values specific to an API |
| **Environment** | When environment active | `pm.environment` | Environment-specific configs |
| **Data** | Current iteration | `pm.iterationData` | Data-driven testing |
| **Local** | Current request/script | `pm.variables` | Temporary values |

**Setting Variables:**

```javascript
// In pre-request or test scripts

// Global variables
pm.globals.set("apiVersion", "v2");

// Collection variables
pm.collectionVariables.set("baseUrl", "https://api.example.com");

// Environment variables
pm.environment.set("authToken", response.token);

// Local variables (temporary)
pm.variables.set("requestId", generateUUID());

// From response data
const response = pm.response.json();
pm.environment.set("userId", response.id);
```

**Getting Variables:**

```javascript
// All scopes (automatic resolution)
const token = pm.variables.get("authToken");

// Specific scopes
const globalVar = pm.globals.get("apiVersion");
const collectionVar = pm.collectionVariables.get("baseUrl");
const envVar = pm.environment.get("databaseUrl");
const dataVar = pm.iterationData.get("testCase");

// In request builder (using {{variable}} syntax)
// URL: {{baseUrl}}/users/{{userId}}
// Headers: Authorization: Bearer {{authToken}}
```

**Variable Examples in Requests:**

**URL:**
```
{{baseUrl}}/api/{{apiVersion}}/users/{{userId}}
```

**Headers:**
```
Authorization: Bearer {{authToken}}
X-Request-ID: {{$guid}}
X-Timestamp: {{$timestamp}}
```

**Request Body:**
```json
{
  "name": "{{userName}}",
  "email": "{{userEmail}}",
  "age": {{userAge}},
  "createdAt": "{{$isoTimestamp}}"
}
```

**Dynamic Variables:**

Postman provides built-in dynamic variables:

| Variable | Description | Example |
|----------|-------------|---------|
| `{{$guid}}` | Random UUID | `123e4567-e89b-12d3-a456-426614174000` |
| `{{$timestamp}}` | Current Unix timestamp | `1614556800` |
| `{{$isoTimestamp}}` | ISO timestamp | `2025-04-24T10:30:00Z` |
| `{{$randomInt}}` | Random integer | `42` |
| `{{$randomFullName}}` | Random name | `John Doe` |
| `{{$randomEmail}}` | Random email | `user123@example.com` |
| `{{$randomPhoneNumber}}` | Random phone | `555-123-4567` |

**Variable Initialization Script:**

```javascript
// Collection pre-request script to initialize common variables
if (!pm.environment.get("initialized")) {
  console.log("Initializing environment variables...");

  // Generate test data
  pm.environment.set("testUser", {
    name: "Test User",
    email: `test-${Date.now()}@example.com`,
    password: "Test@123"
  });

  // Set timestamps
  pm.environment.set("testStartTime", new Date().toISOString());
  pm.environment.set("initialized", true);
}
```

**Variable Visualization:**

```javascript
// Quick view of all variables in current scope
console.log("=== CURRENT VARIABLES ===");
console.log("Global:", pm.globals.toObject());
console.log("Collection:", pm.collectionVariables.toObject());
console.log("Environment:", pm.environment.toObject());
console.log("Local:", pm.variables.toObject());
```

**Key Insight:** Variables are the key to reusability. A well-variable-ized collection can run in development, staging, and production with just a change of environment.

Environments let you switch between different configurations without changing your requests. They're essential for testing across development, staging, and production.

**What Are Environments?**

An environment is a set of key-value pairs that override variables with the same name. They let you:
- Switch between different API endpoints
- Use different credentials per environment
- Test with environment-specific data
- Share configurations across team members

**Common Environment Types:**

```json
// Development Environment
{
  "baseUrl": "http://localhost:3000",
  "apiKey": "dev-api-key-123",
  "database": "dev-db",
  "logLevel": "debug",
  "timeout": 5000
}

// Staging Environment
{
  "baseUrl": "https://staging-api.example.com",
  "apiKey": "staging-api-key-456",
  "database": "staging-db",
  "logLevel": "info",
  "timeout": 3000
}

// Production Environment
{
  "baseUrl": "https://api.example.com",
  "apiKey": "prod-api-key-789",
 "database": "prod-db",
  "logLevel": "error",
  "timeout": 2000
}
```

**Creating an Environment:**

1. Click "Environments" in the left sidebar
2. Click "+ Add" to create a new environment
3. Name it (e.g., "Development")
4. Add variables as key-value pairs
5. Click "Save"

**Environment Variables Examples:**

| Variable | Development | Staging | Production |
|----------|-------------|---------|------------|
| `baseUrl` | `localhost:3000` | `staging-api.example.com` | `api.example.com` |
| `apiKey` | `dev-key` | `staging-key` | `prod-key` |
| `adminUser` | `admin@dev.com` | `admin@staging.com` | `admin@prod.com` |
| `adminPass` | `dev-pass` | `staging-pass` | `prod-pass` |
| `timeoutMs` | `5000` | `3000` | `2000` |
| `features` | `all` | `limited` | `stable` |

**Using Environments:**

1. Select environment from top-right dropdown
2. All requests will use environment variables
3. Variables appear as `{{variableName}}` in requests

**Environment-Specific Scripts:**

```javascript
// Pre-request script that behaves differently per environment
const env = pm.environment.name;

if (env === "Development") {
  console.log("🔧 Development mode - verbose logging enabled");
  pm.variables.set("logBody", true);
} else if (env === "Staging") {
  console.log("🧪 Staging - using test data");
  pm.variables.set("testUser", "staging-test@example.com");
} else if (env === "Production") {
  console.log("🚀 Production - careful mode");
  // Add extra validation in production
  pm.variables.set("validateSsl", true);
}
```

**Environment Chaining:**

Create base environments and extend them:

```javascript
// Base environment (inherited)
{
  "apiVersion": "v2",
  "timeout": 5000,
  "retryCount": 3
}

// Development (overrides base)
{
  "baseUrl": "localhost:3000",
  "apiKey": "dev-key",
  "timeout": 10000  // Longer timeout for dev
}

// Production (overrides base)
{
  "baseUrl": "api.example.com",
  "apiKey": "prod-key",
  "timeout": 2000   // Stricter timeout for prod
}
```

**Environment Quick Switcher:**

Create scripts to quickly switch environments:

```javascript
// Quick switch function (run in Postman Console)
function switchTo(envName) {
  const environments = {
    dev: "Development",
    staging: "Staging",
    prod: "Production"
  };

  const env = environments[envName];
  if (env) {
    // This requires Postman API - for demonstration
    console.log(`Switching to ${env}...`);
    // In practice, use the dropdown manually
  }
}

// Usage: switchTo('dev')
```

**Exporting and Sharing Environments:**

1. Click on environment
2. Click "Export" (download as JSON)
3. Share file with team or import in another Postman instance

**Environment Best Practices:**

| Do | Don't |
|----|-------|
| ✅ Use descriptive variable names | ❌ Hardcode environment-specific values |
| ✅ Document each variable's purpose | ❌ Share sensitive values (use secrets) |
| ✅ Keep environments in sync | ❌ Have too many environment variables |
| ✅ Test environment switching | ❌ Forget to switch environments |
| ✅ Use secrets for sensitive data | ❌ Commit environment files to git |

**Environment Variables with Secrets:**

For sensitive data, use Postman's secret variables:

```javascript
// Setting a secret (masked in UI)
pm.environment.set("apiSecret", "super-secret-value", true);

// Using secrets
// Headers: X-API-Secret: {{apiSecret}}
// The value will be masked in the UI
```

**Key Insight:** Environments make your collections portable. One collection, many configurations. Master environments to master Postman.

Pre-request scripts run before your API request is sent. They're perfect for setting up data, generating dynamic values, and handling authentication.

**What Can Pre-request Scripts Do?**

- Generate dynamic test data
- Calculate timestamps and signatures
- Set environment variables
- Log request details
- Handle complex authentication flows
- Modify request parameters
- Conditionally skip requests

**Basic Pre-request Script Examples:**

```javascript
// Set a timestamp header
const timestamp = Date.now();
pm.request.headers.add({
  key: "X-Timestamp",
  value: timestamp.toString()
});

// Generate a random email for testing
const randomEmail = `user-${Math.floor(Math.random() * 10000)}@test.com`;
pm.variables.set("testEmail", randomEmail);

// Log what's happening
console.log(`🔧 Preparing request to ${pm.request.url}`);
console.log(`📧 Using test email: ${randomEmail}`);
```

**Authentication Pre-request Scripts:**

**Bearer Token:**
```javascript
// Check if token exists and is valid
const token = pm.environment.get("authToken");
const tokenExpiry = pm.environment.get("tokenExpiry");

if (!token || Date.now() > tokenExpiry) {
  console.log("🔄 Token expired or missing, refreshing...");

  // Make authentication request (simulated)
  // In reality, you'd use pm.sendRequest()
  const newToken = "eyJhbGci...";
  const expiresIn = 3600 * 1000; // 1 hour

  pm.environment.set("authToken", newToken);
  pm.environment.set("tokenExpiry", Date.now() + expiresIn);
}

// Add token to request
pm.request.headers.add({
  key: "Authorization",
  value: `Bearer ${pm.environment.get("authToken")}`
});
```

**AWS Signature v4:**
```javascript
// AWS Signature v4 generation (simplified)
const awsCredentials = {
  accessKey: pm.environment.get("awsAccessKey"),
  secretKey: pm.environment.get("awsSecretKey"),
  region: "us-east-1",
  service: "execute-api"
};

// Generate signature (simplified - use crypto library in reality)
const date = new Date().toISOString().replace(/[:-]/g, '').split('.')[0] + 'Z';
const signature = generateSignature(awsCredentials, date); // Custom function

pm.request.headers.add({
  key: "Authorization",
  value: `AWS4-HMAC-SHA256 Credential=${awsCredentials.accessKey}/${date}/${awsCredentials.region}/${awsCredentials.service}/aws4_request, SignedHeaders=host;x-amz-date, Signature=${signature}`
});
```

**Data Generation Scripts:**

```javascript
// Generate realistic test data
const testData = {
  user: {
    firstName: ["John", "Jane", "Bob", "Alice"][Math.floor(Math.random() * 4)],
    lastName: ["Smith", "Doe", "Johnson", "Brown"][Math.floor(Math.random() * 4)],
    age: Math.floor(Math.random() * 50) + 18,
    email: `test-${Date.now()}@example.com`,
    address: {
      street: `${Math.floor(Math.random() * 1000)} Main St`,
      city: ["New York", "Los Angeles", "Chicago", "Houston"][Math.floor(Math.random() * 4)],
      zip: Math.floor(Math.random() * 90000) + 10000
    }
  }
};

// Save as variables
pm.variables.set("userFirstName", testData.user.firstName);
pm.variables.set("userLastName", testData.user.lastName);
pm.variables.set("userEmail", testData.user.email);
pm.variables.set("userAddress", JSON.stringify(testData.user.address));
```

**Conditional Request Logic:**

```javascript
// Skip request if conditions aren't met
const requiredVars = ["baseUrl", "authToken", "userId"];
const missingVars = requiredVars.filter(v => !pm.variables.get(v));

if (missingVars.length > 0) {
  console.error(`❌ Missing required variables: ${missingVars.join(", ")}`);
  postman.setNextRequest(null); // Stop execution
}

// Run different requests based on environment
if (pm.environment.name === "Production") {
  console.log("🏭 Production - using minimal test data");
  pm.variables.set("testIntensity", "low");
} else {
  console.log("🧪 Non-production - full test data");
  pm.variables.set("testIntensity", "high");
}
```

**Making HTTP Requests in Pre-request Scripts:**

```javascript
// Fetch data from another API before main request
pm.sendRequest({
  url: "https://api.example.com/auth/token",
  method: "POST",
  header: {
    "Content-Type": "application/json"
  },
  body: {
    mode: "raw",
    raw: JSON.stringify({
      username: pm.environment.get("apiUser"),
      password: pm.environment.get("apiPass")
    })
  }
}, function(err, response) {
  if (err) {
    console.error("❌ Auth failed:", err);
    throw new Error("Authentication failed");
  }

  const token = response.json().token;
  pm.environment.set("authToken", token);
  console.log("✅ Auth token obtained");
});
```

**Crypto and Hashing:**

```javascript
// Using CryptoJS (available in Postman sandbox)
const CryptoJS = require("crypto-js");

// Generate MD5 hash
const data = JSON.stringify(pm.request.body);
const hash = CryptoJS.MD5(data).toString();
pm.variables.set("bodyHash", hash);

// Generate SHA256 signature
const secret = pm.environment.get("apiSecret");
const signature = CryptoJS.HmacSHA256(data, secret).toString();
pm.request.headers.add({
  key: "X-Signature",
  value: signature
});

// Generate random strings
const randomId = CryptoJS.lib.WordArray.random(16).toString();
pm.variables.set("requestId", randomId);
```

**Request Modification:**

```javascript
// Modify request URL
const baseUrl = pm.variables.get("baseUrl");
const userId = pm.variables.get("userId");
pm.request.url = `${baseUrl}/users/${userId}`;

// Add query parameters
pm.request.url.addQueryParams([
  { key: "include", value: "profile,orders" },
  { key: "timestamp", value: Date.now().toString() }
]);

// Modify request body
if (pm.request.body && pm.request.body.raw) {
  const body = JSON.parse(pm.request.body.raw);
  body.requestId = CryptoJS.lib.WordArray.random(8).toString();
  body.timestamp = new Date().toISOString();
  pm.request.body.raw = JSON.stringify(body);
}
```

**Debugging Pre-request Scripts:**

```javascript
// Comprehensive logging
console.log("🔍 PRE-REQUEST SCRIPT DEBUG");
console.log("Environment:", pm.environment.name);
console.log("Request Method:", pm.request.method);
console.log("Request URL:", pm.request.url.toString());
console.log("Headers:", pm.request.headers.toObject());
console.log("Variables:", {
  global: pm.globals.toObject(),
  collection: pm.collectionVariables.toObject(),
  environment: pm.environment.toObject(),
  local: pm.variables.toObject()
});

if (pm.request.body) {
  console.log("Request Body:", pm.request.body.toString());
}
```

**Key Insight:** Pre-request scripts turn static requests into dynamic workflows. They're the automation engine of Postman.

Postman's test scripts let you validate API responses programmatically. They transform Postman from a request tool into a testing framework.

**Test Structure:**

```javascript
// Basic test structure
pm.test("Test name describes what you're checking", function() {
  // Assertions go here
  pm.expect(true).to.be.true;
});
```

**Common Test Scenarios:**

**Status Code Tests:**
```javascript
// Check successful response
pm.test("Status code is 200", () => {
  pm.response.to.have.status(200);
});

// Check multiple possible status codes
pm.test("Status code is either 200 or 201", () => {
  pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

// Check error status
pm.test("Status code is 400 for bad request", () => {
  pm.response.to.have.status(400);
});
```

**Response Body Tests:**
```javascript
// Parse response body
const response = pm.response.json();

// Check property existence
pm.test("Response has id field", () => {
  pm.expect(response).to.have.property("id");
});

// Check exact value
pm.test("User name matches expected", () => {
  pm.expect(response.name).to.equal("John Doe");
});

// Check type
pm.test("ID is a number", () => {
  pm.expect(response.id).to.be.a("number");
});

// Check array length
pm.test("Returns exactly 10 items", () => {
  pm.expect(response.items).to.have.lengthOf(10);
});

// Check nested properties
pm.test("Address has street and city", () => {
  pm.expect(response.address).to.include.keys("street", "city");
});
```

**Header Tests:**
```javascript
// Check header exists
pm.test("Content-Type header is present", () => {
  pm.response.to.have.header("Content-Type");
});

// Check header value
pm.test("Content-Type is application/json", () => {
  pm.response.to.have.header("Content-Type", "application/json; charset=utf-8");
});

// Check custom headers
pm.test("X-RateLimit-Remaining header exists", () => {
  pm.response.to.have.header("X-RateLimit-Remaining");
});
```

**Response Time Tests:**
```javascript
// Check response time
pm.test("Response time is less than 200ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(200);
});

// More granular timing
pm.test("Response performance is acceptable", () => {
  const time = pm.response.responseTime;
  if (time < 100) {
    console.log("🚀 Super fast!");
  } else if (time < 200) {
    console.log("✅ Good performance");
  } else if (time < 500) {
    console.log("⚠️ Acceptable but slow");
  } else {
    console.log("🐢 Too slow!");
    pm.expect(time).to.be.below(500); // Fail if too slow
  }
});
```

**Advanced Assertions:**

**Schema Validation:**
```javascript
// Define expected schema
const userSchema = {
  type: "object",
  required: ["id", "name", "email"],
  properties: {
    id: { type: "number" },
    name: { type: "string", minLength: 1 },
    email: { type: "string", pattern: "^[^@]+@[^@]+\.[^@]+$" },
    age: { type: "number", minimum: 0, maximum: 150 },
    createdAt: { type: "string", format: "date-time" }
  }
};

pm.test("Response matches schema", () => {
  const response = pm.response.json();
  const validate = tv4.validate(response, userSchema);
  pm.expect(validate).to.be.true;
});
```

**Data-Driven Tests:**
```javascript
// Test multiple conditions
const testCases = [
  { field: "id", type: "number", required: true },
  { field: "name", type: "string", required: true },
  { field: "email", type: "string", required: true },
  { field: "age", type: "number", required: false }
];

const response = pm.response.json();

testCases.forEach(({ field, type, required }) => {
  pm.test(`Field '${field}' is ${required ? 'present' : 'optional'}`, () => {
    if (required) {
      pm.expect(response).to.have.property(field);
    }
  });

  if (required) {
    pm.test(`Field '${field}' is of type ${type}`, () => {
      pm.expect(typeof response[field]).to.equal(type);
    });
  }
});
```

**Extracting Data for Later Use:**
```javascript
// Save data for subsequent requests
pm.test("Extract user data", () => {
  const response = pm.response.json();

  // Save to environment
  pm.environment.set("userId", response.id);
  pm.environment.set("userEmail", response.email);

  // Save to collection variables
  pm.collectionVariables.set("lastCreatedUser", response);

  // Log for debugging
  console.log(`✅ Created user: ${response.name} (ID: ${response.id})`);
});

// Extract multiple items from array
pm.test("Extract product IDs", () => {
  const response = pm.response.json();
  const productIds = response.products.map(p => p.id);
  pm.environment.set("productIds", JSON.stringify(productIds));
});
```

**Conditional Tests:**
```javascript
// Different assertions based on environment
if (pm.environment.name === "Production") {
  pm.test("Production: Strict validation", () => {
    const response = pm.response.json();
    pm.expect(response).to.have.all.keys("id", "name", "email", "createdAt");
    pm.expect(response.createdAt).to.match(/^\d{4}-\d{2}-\d{2}T/);
  });
} else {
  pm.test("Development: Basic validation", () => {
    const response = pm.response.json();
    pm.expect(response).to.have.property("id");
  });
}
```

**Error Response Testing:**
```javascript
// Test error scenarios
pm.test("Error response has correct format", () => {
  const error = pm.response.json();

  pm.expect(pm.response.code).to.be.oneOf([400, 401, 403, 404, 500]);
  pm.expect(error).to.have.property("error");
  pm.expect(error).to.have.property("message");
  pm.expect(error).to.have.property("statusCode", pm.response.code);
});

// Test specific error message
pm.test("Error message indicates validation failure", () => {
  const error = pm.response.json();
  pm.expect(error.message).to.include("validation");
});
```

**Test Organization Best Practices:**

```javascript
// Group related tests
pm.test("=== User Creation Tests ===", () => console.log("Starting user tests"));

// Status tests
pm.test("✅ Status code is 201 Created", () => {
  pm.response.to.have.status(201);
});

// Header tests
pm.test("✅ Location header points to new user", () => {
  pm.response.to.have.header("Location");
  const location = pm.response.headers.get("Location");
  pm.expect(location).to.include("/users/");
});

// Body tests
const user = pm.response.json();

pm.test("✅ User has all required fields", () => {
  pm.expect(user).to.have.all.keys("id", "name", "email", "createdAt");
});

pm.test("✅ User ID is a number", () => {
  pm.expect(user.id).to.be.a("number");
});

pm.test("✅ Email format is valid", () => {
  pm.expect(user.email).to.match(/^[^@]+@[^@]+\.[^@]+$/);
});

// Performance test
pm.test("✅ Response time acceptable", () => {
  pm.expect(pm.response.responseTime).to.be.below(300);
});
```

**Test Result Visualization:**
```javascript
// Create a test summary
const tests = {
  total: 0,
  passed: 0,
  failed: 0
};

// This would need to be implemented with Postman's test events
// Conceptual example
pm.test("Test suite complete", () => {
  console.log("📊 TEST SUMMARY");
  console.log(`Total: ${tests.total}`);
  console.log(`✅ Passed: ${tests.passed}`);
  console.log(`❌ Failed: ${tests.failed}`);
  console.log(`Success rate: ${(tests.passed/tests.total*100).toFixed(1)}%`);
});
```

**Key Insight:** Tests turn Postman from a manual tool into an automated testing platform. Good tests catch bugs early and give you confidence in your APIs.

Postman Monitors run your collections on a schedule, continuously checking your APIs for uptime, performance, and correctness. They're like having a robot tester watching your APIs 24/7.

**What Are Monitors?**

Monitors are scheduled runs of Postman collections in the cloud. They:
- Run collections on a schedule (every 5 minutes to monthly)
- Execute in Postman's cloud infrastructure
- Send alerts on failures
- Track performance over time
- Provide historical results

**Monitor Architecture:**

```
┌─────────────────────────────────────────────────────────────────┐
│                      POSTMAN MONITORS                              │
├─────────────────────────────────────────────────────────────────┤
│                                                                   │
│  Your Collection ──→ Postman Cloud ──→ Scheduled Execution        │
│        ↑                  ↓                                       │
│        │            Results Database                              │
│        │                  ↓                                       │
│        └────────── Alerts & Reports                               │
│                                                                   │
│  Monitor Features:                                                │
│  • Scheduled runs                                                 │
│  • Regional execution                                             │
│  • Performance tracking                                           │
│  • Failure alerts (email, Slack, webhook)                         │
│  • Historical trends                                              │
│  • Uptime calculations                                            │
│                                                                   │
└─────────────────────────────────────────────────────────────────┘
```

**Creating a Monitor:**

1. **Prepare your collection:**
   - Include tests for validation
   - Use environment variables
   - Keep run time reasonable

2. **Create monitor:**
   - In Postman, go to "Monitors" tab
   - Click "Create Monitor"
   - Select collection and environment
   - Configure schedule
   - Set up alerts

3. **Monitor Configuration:**

```json
{
  "name": "Production API Health Check",
  "collection": "API Health Collection",
  "environment": "Production Environment",
  "schedule": {
    "frequency": "every 30 minutes",
    "timezone": "UTC"
  },
  "requestTimeout": 30000,
  "alerts": [
    { "type": "email", "recipients": ["team@example.com"] },
    { "type": "slack", "webhook": "https://hooks.slack.com/..." }
  ],
  "regions": ["us-east-1", "eu-west-1", "ap-southeast-1"]
}
```

**What to Monitor:**

| Monitor Type | Frequency | What to Check | Example |
|--------------|-----------|---------------|---------|
| **Uptime** | Every 5-15 min | API availability | GET /health returns 200 |
| **Critical Flows** | Hourly | Business-critical paths | User login → dashboard |
| **Performance** | Hourly | Response times | All endpoints < 500ms |
| **Regression** | Daily | Full test suite | All endpoints, all tests |
| **SLA Compliance** | Continuous | Uptime and performance | 99.9% uptime, <1s response |

**Sample Health Check Collection:**

```javascript
// Request: GET /health
// Tests:
pm.test("API is up and running", () => {
  pm.response.to.have.status(200);
});

pm.test("Response indicates healthy status", () => {
  const health = pm.response.json();
  pm.expect(health.status).to.equal("healthy");
});

pm.test("Database connection is working", () => {
  const health = pm.response.json();
  pm.expect(health.database).to.equal("connected");
});

pm.test("Response time is acceptable for monitoring", () => {
  pm.expect(pm.response.responseTime).to.be.below(1000);
});
```

**Monitor Alerts and Notifications:**

**Email Alerts:**
```json
{
  "alerts": {
    "email": {
      "recipients": ["devops@example.com", "qa@example.com"],
      "onFailure": true,
      "onRecovery": true,
      "onPerformanceDegradation": true
    }
  }
}
```

**Slack Integration:**
```javascript
// In your test scripts
pm.test("Send alert to Slack on failure", () => {
  if (pm.response.code !== 200) {
    // Monitor will handle this automatically if configured
    console.error("❌ API returned non-200 status");
  }
});
```

**Webhook Alerts:**
```javascript
// Custom webhook integration
pm.test("Alert via webhook", () => {
  if (pm.response.code !== 200) {
    // Monitor can send webhook on failure
    // Configure in monitor settings
  }
});
```

**Monitor Performance Tracking:**

```javascript
// Track performance metrics
pm.test("Track response time", () => {
  const time = pm.response.responseTime;

  // Performance categories
  if (time < 200) {
    console.log(`✅ Excellent: ${time}ms`);
  } else if (time < 500) {
    console.log(`⚠️ Acceptable: ${time}ms`);
  } else {
    console.log(`❌ Slow: ${time}ms`);
    // This will trigger alerts if configured
  }

  // Store for trend analysis
  pm.environment.set(`responseTime_${Date.now()}`, time);
});
```

**Multi-Region Monitoring:**

Postman can run monitors from different AWS regions:

```javascript
// Check region-specific behavior
pm.test("Check region-specific response", () => {
  const region = pm.environment.get("region");

  if (region === "us-east-1") {
    pm.expect(pm.response.json().dataCenter).to.equal("Virginia");
  } else if (region === "eu-west-1") {
    pm.expect(pm.response.json().dataCenter).to.equal("Ireland");
  }
});
```

**Monitor Dashboard Analysis:**

Key metrics to watch:

| Metric | What It Tells You | Action Threshold |
|--------|-------------------|------------------|
| **Uptime %** | API availability | < 99.9% investigate |
| **Avg Response Time** | Performance trend | > 500ms investigate |
| **Failure Rate** | Test failures | > 1% investigate |
| **Run Duration** | Collection execution time | Increasing over time |
| **Regional Variance** | Geo-performance | > 200ms difference |

**Monitor Best Practices:**

1. **Start Simple:**
   ```javascript
   // Initial monitor - just check uptime
   pm.test("API is reachable", () => {
     pm.response.to.have.status(200);
   });
   ```

2. **Add Critical Tests Gradually:**
   ```javascript
   // Week 2 - Add authentication check
   pm.test("Auth endpoint working", () => {
     pm.response.to.have.status(200);
   });
   ```

3. **Monitor Business-Critical Flows:**
   ```javascript
   // Full user journey
   // Request 1: Login
   // Request 2: Get dashboard
   // Request 3: Perform key action
   ```

4. **Set Appropriate Schedules:**
   ```javascript
   // Production: Every 5 minutes
   // Staging: Every hour
   // Development: Every 6 hours
   ```

5. **Configure Meaningful Alerts:**
   ```javascript
   // Alert on patterns, not single failures
   if (consecutiveFailures > 3) {
     // Send urgent alert
   }
   ```

**Sample Monitor Collection Structure:**

```javascript
{
  "info": {
    "name": "Production Monitors",
    "description": "24/7 monitoring of production APIs"
  },
  "item": [
    {
      "name": "Health Checks",
      "item": [
        { "name": "GET /health" },
        { "name": "GET /metrics" },
        { "name": "GET /version" }
      ]
    },
    {
