**Token Management:**

```java
public class TokenManager {
    private static String token;
    private static Instant tokenExpiry;

    public static String getToken() {
        if (token == null || Instant.now().isAfter(tokenExpiry)) {
            refreshToken();
        }
        return token;
    }

    private static void refreshToken() {
        // Make auth request to get new token
        Map<String, String> credentials = new HashMap<>();
        credentials.put("username", Config.getUsername());
        credentials.put("password", Config.getPassword());

        AuthResponse response = given()
            .contentType(ContentType.JSON)
            .body(credentials)
        .when()
            .post(Config.getAuthUrl() + "/login")
        .then()
            .statusCode(200)
            .extract()
            .as(AuthResponse.class);

        token = response.getToken();
        tokenExpiry = Instant.now().plusSeconds(response.getExpiresIn());
    }
}

// Usage in tests
@Test
public void testWithAutomaticTokenRefresh() {
    given()
        .auth().oauth2(TokenManager.getToken())
        .get("/secured")
    .then()
        .statusCode(200);
}
