public class CustomMapping {

    // Configure ObjectMapper
    @BeforeAll
    public static void setup() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.setDateFormat(new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'"));
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        RestAssured.config = RestAssured.config()
            .objectMapperConfig(new ObjectMapperConfig()
                .jackson2ObjectMapperFactory((cls, charset) -> mapper));
    }

    // Custom deserializer
    public static class UserDeserializer extends JsonDeserializer<User> {
        @Override
        public User deserialize(JsonParser p, DeserializationContext ctxt) 
                throws IOException {
            JsonNode node = p.getCodec().readTree(p);

            return User.builder()
                .id(node.get("user_id").asLong())
                .name(node.get("full_name").asText())
                .email(node.get("email_address").asText())
                .build();
        }
    }
}
