**Filters for Cross-Cutting Concerns:**

```java
public class CustomFilters {

    // Timing filter
    public static Filter timingFilter() {
        return (req, res, ctx) -> {
            long start = System.nanoTime();
            Response response = ctx.next(req, res);
            long duration = System.nanoTime() - start;

            System.out.println(String.format(
                "Request to %s took %d ms",
                req.getPath(),
                TimeUnit.NANOSECONDS.toMillis(duration)
            ));

            return response;
        };
    }

    // Retry filter
    public static Filter retryFilter(int maxRetries) {
        return (req, res, ctx) -> {
            int retries = 0;
            while (retries < maxRetries) {
                try {
                    return ctx.next(req, res);
                } catch (Exception e) {
                    retries++;
                    if (retries >= maxRetries) {
                        throw e;
                    }
                    try {
                        Thread.sleep(1000 * retries);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException(ie);
                    }
                }
            }
            return null;
        };
    }

    // Authentication filter
    public static Filter authFilter(Supplier<String> tokenSupplier) {
        return (req, res, ctx) -> {
            req.header("Authorization", "Bearer " + tokenSupplier.get());
            return ctx.next(req, res);
        };
    }

    // Usage
    @Test
    public void testWithFilters() {
        given()
            .filter(timingFilter())
            .filter(retryFilter(3))
            .filter(authFilter(() -> TokenManager.getToken()))
            .get("/users")
        .then()
            .statusCode(200);
    }
}
