**2. Base API Client (utils/api_client.py):**

```python
import requests
import logging
import time
from typing import Optional, Dict, Any, Union
from requests.exceptions import RequestException, Timeout, ConnectionError
from config.settings import settings

logger = logging.getLogger(__name__)

class APIError(Exception):
    """Custom API exception"""
    def __init__(self, message: str, response: Optional[requests.Response] = None):
        self.message = message
        self.response = response
        self.status_code = response.status_code if response else None
        super().__init__(self.message)

class APIClient:
    """Base API client with retry logic and error handling"""

    def __init__(self, base_url: str = settings.BASE_URL, api_key: Optional[str] = None):
        self.base_url = base_url.rstrip('/')
        self.session = requests.Session()

        # Configure retry adapter
        self.session.mount('https://', requests.adapters.HTTPAdapter(
            max_retries=settings.MAX_RETRIES,
            pool_connections=20,
            pool_maxsize=20
        ))

        # Default headers
        self.session.headers.update({
            'User-Agent': 'APITestFramework/1.0',
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        })

        if api_key:
            self.session.headers.update({'X-API-Key': api_key})

        self.auth_token = None

    def set_auth_token(self, token: str):
        """Set Bearer token for authentication"""
        self.auth_token = token
        self.session.headers.update({'Authorization': f'Bearer {token}'})

    def _request(self, method: str, endpoint: str, **kwargs) -> requests.Response:
        """Internal request method with logging and error handling"""
        url = f"{self.base_url}/{endpoint.lstrip('/')}"

        # Set default timeout if not provided
        if 'timeout' not in kwargs:
            kwargs['timeout'] = (settings.CONNECTION_TIMEOUT, settings.READ_TIMEOUT)

        # Log request
        logger.info(f"{method} {url}")
        if 'json' in kwargs:
            logger.debug(f"Request body: {kwargs['json']}")

        start_time = time.time()

        try:
            response = self.session.request(method, url, **kwargs)
            elapsed = time.time() - start_time

            # Log response
            logger.info(f"Response: {response.status_code} ({elapsed:.2f}s)")

            # Try to log response body for debugging
            if response.content:
                try:
                    logger.debug(f"Response body: {response.json()}")
                except:
                    logger.debug(f"Response body (text): {response.text[:200]}")

            return response

        except Timeout as e:
            logger.error(f"Timeout after {time.time() - start_time:.2f}s")
            raise APIError(f"Request timeout: {str(e)}")
        except ConnectionError as e:
            logger.error(f"Connection error: {str(e)}")
            raise APIError(f"Connection error: {str(e)}")
        except RequestException as e:
            logger.error(f"Request failed: {str(e)}")
            raise APIError(f"Request failed: {str(e)}")

    def get(self, endpoint: str, **kwargs) -> requests.Response:
        """GET request"""
        return self._request('GET', endpoint, **kwargs)

    def post(self, endpoint: str, **kwargs) -> requests.Response:
        """POST request"""
        return self._request('POST', endpoint, **kwargs)

    def put(self, endpoint: str, **kwargs) -> requests.Response:
        """PUT request"""
