stubFor(post("/echo")
    .willReturn(aResponse()
        .withTransformers("response-template")
        .withBody("{\"youSent\":\"{{request.body}}\"}")));

// Access request data in response
stubFor(get("/users/{{request.pathSegments.[1]}}")
    .willReturn(aResponse()
        .withTransformers("response-template")
        .withBody("{\"id\":{{request.pathSegments.[1]}},\"name\":\"User\"}")));

// Use handlebars helpers
