```

**Stateful Mocks**

```java
// Scenario-based stateful behavior
stubFor(post("/order")
    .inScenario("Order Processing")
    .whenScenarioStateIs(Scenario.STARTED)
    .willReturn(aResponse()
        .withStatus(201)
        .withBody("{\"status\":\"created\"}"))
    .willSetStateTo("OrderCreated"));

stubFor(get("/order/1")
    .inScenario("Order Processing")
    .whenScenarioStateIs("OrderCreated")
    .willReturn(aResponse()
        .withStatus(200)
        .withBody("{\"status\":\"processing\"}")));

stubFor(delete("/order/1")
    .inScenario("Order Processing")
    .whenScenarioStateIs("OrderCreated")
    .willReturn(aResponse()
        .withStatus(204))
    .willSetStateTo(Scenario.STARTED));  // Reset
```

