            .withQueryParam("name", matching(".*"))
            .willReturn(aResponse()
                .withTransformers("response-template")
                .withTransformerParameter("testData", testData)
                .withBody("""
                    [
                        {{#each testData}}
                        {{#if (contains name request.query.name)}}
                        {
                            "id": {{id}},
                            "name": "{{name}}",
                            "value": {{value}}
                        }{{#unless @last}},{{/unless}}
                        {{/if}}
                        {{/each}}
                    ]
                    """)));
    }
}
```

**Pattern 8: Chaos Engineering with Mocks**

Use mocks to test system resilience:

```java
// Chaos testing configuration
@Test
public void testResilience() {
    // Configure mock for chaos
    stubFor(get("/payment/process")
        .inScenario("Chaos")
        .willReturn(aResponse()
            .withStatus(200))
        .willSetStateTo("Normal"));

    // Add chaotic behavior
    stubFor(get("/payment/process")
        .inScenario("Chaos")
        .whenScenarioStateIs("Normal")
        .willReturn(aResponse()
            .withStatus(500)
            .withBody("Internal Server Error"))
        .willSetStateTo("Failure"));

    stubFor(get("/payment/process")
        .inScenario("Chaos")
        .whenScenarioStateIs("Failure")
        .willReturn(aResponse()
            .withFixedDelay(30000)  // Timeout
            .withFault(Fault.CONNECTION_RESET_BY_PEER))
        .willSetStateTo("Timeout"));

    stubFor(get("/payment/process")
        .inScenario("Chaos")
        .whenScenarioStateIs("Timeout")
        .willReturn(aResponse()
            .withStatus(503)
            .withBody("Service Unavailable"))
        .willSetStateTo(Scenario.STARTED));  // Reset

    // Test retry logic
    for (int i = 0; i < 10; i++) {
        try {
            myService.processPayment();
        } catch (Exception e) {
            // Expected failures
        }
    }
}
```

**Pattern 9: SLA Compliance Testing**

Test if your system meets SLAs when dependencies are slow:

```java
@Test
public void testSLACompliance() {
    // Configure slow dependencies
    stubFor(get("/database/query")
        .willReturn(aResponse()
            .withFixedDelay(800)));  // 800ms

    stubFor(get("/auth/validate")
        .willReturn(aResponse()
            .withFixedDelay(300)));  // 300ms

    // Measure end-to-end response time
    long start = System.currentTimeMillis();
    myService.getUserData(1);
    long duration = System.currentTimeMillis() - start;

    // Should be less than sum of dependencies + own processing
    assertTrue(duration < 1200, "SLA exceeded");
}
