public class BalancedTestingStrategy {

    private static final String ENV = System.getenv("TEST_ENV");

    @Test
    public void testPaymentFlow() {
        // Use mocks for expensive/unreliable services
        if (ENV.equals("CI")) {
            // In CI, use mocks for everything except our service
            mockAllDownstreamServices();
        } else if (ENV.equals("STAGING")) {
            // In staging, test against real downstream if available
            useRealServicesIfAvailable();
        } else if (ENV.equals("PERF")) {
