```

**Sample K6 Test**

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';

// Custom metrics
const errorRate = new Rate('errors');
const responseTimeTrend = new Trend('response_time');

export let options = {
  stages: [
    { duration: '1m', target: 10 },   // Ramp up to 10 users
    { duration: '3m', target: 10 },   // Stay at 10 users
    { duration: '1m', target: 20 },   // Ramp up to 20
    { duration: '3m', target: 20 },   // Stay at 20
    { duration: '1m', target: 0 },    // Ramp down
  ],
  thresholds: {
    http_req_duration: ['p(95)<500'], // 95% of requests under 500ms
    http_req_failed: ['rate<0.01'],   // Less than 1% errors
    'errors': ['rate<0.05'],          // Custom metric threshold
  },
};

export default function() {
  // GET request
  let res = http.get('https://api.example.com/users/1');

  // Check response
  let success = check(res, {
    'status is 200': (r) => r.status === 200,
    'has user id': (r) => r.json().id !== undefined,
  });

  // Record custom metrics
  errorRate.add(!success);
  responseTimeTrend.add(res.timings.duration);

  // Think time
  sleep(Math.random() * 2);
}

// Setup and teardown functions
export function setup() {
  // Get authentication token once
  let res = http.post('https://api.example.com/auth/login', 
    JSON.stringify({ username: 'test', password: 'test' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  return { token: res.json().token };
}

export function teardown(data) {
  // Cleanup after test
  http.post('https://api.example.com/auth/logout', null, {
    headers: { 'Authorization': `Bearer ${data.token}` }
  });
}
```

