**Browser-Side RUM (JavaScript)**

```javascript
// rum-client.js
class RUMCollector {
    constructor(config) {
        this.apiUrl = config.apiUrl;
        this.sampleRate = config.sampleRate || 1.0;
        this.batchSize = config.batchSize || 10;
        this.buffer = [];

        // Intercept fetch requests
        this.interceptFetch();

        // Intercept XMLHttpRequest
        this.interceptXHR();

        // Send batched data periodically
        setInterval(() => this.flush(), 5000);
    }

    shouldSample() {
        return Math.random() < this.sampleRate;
    }

    interceptFetch() {
        const originalFetch = window.fetch;
        window.fetch = async (...args) => {
            if (!this.shouldSample()) {
                return originalFetch(...args);
            }

            const startTime = performance.now();
            const requestId = this.generateId();

            try {
                const response = await originalFetch(...args);
                const duration = performance.now() - startTime;

                this.recordRequest({
                    id: requestId,
                    url: args[0],
                    method: args[1]?.method || 'GET',
                    status: response.status,
                    duration: duration,
                    timestamp: new Date().toISOString(),
                    success: response.ok
                });

                return response;
            } catch (error) {
                const duration = performance.now() - startTime;

                this.recordRequest({
                    id: requestId,
                    url: args[0],
                    method: args[1]?.method || 'GET',
                    error: error.message,
                    duration: duration,
                    timestamp: new Date().toISOString(),
                    success: false
                });

                throw error;
            }
        };
    }

    recordRequest(data) {
        // Add client metadata
        data.userAgent = navigator.userAgent;
        data.viewport = {
            width: window.innerWidth,
            height: window.innerHeight
        };
        data.connection = navigator.connection?.effectiveType;

        this.buffer.push(data);

        if (this.buffer.length >= this.batchSize) {
            this.flush();
        }
    }

    flush() {
        if (this.buffer.length === 0) return;

        const batch = [...this.buffer];
        this.buffer = [];

        // Use sendBeacon for reliable delivery during page unload
        if (navigator.sendBeacon) {
            const blob = new Blob([JSON.stringify(batch)], {
                type: 'application/json'
            });
            navigator.sendBeacon(`${this.apiUrl}/rum`, blob);
        } else {
            fetch(`${this.apiUrl}/rum`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(batch),
                keepalive: true
            }).catch(err => console.error('RUM send failed:', err));
        }
    }

    generateId() {
        return Math.random().toString(36).substring(2) + Date.now().toString(36);
    }
}

// Initialize
new RUMCollector({
    apiUrl: 'https://api.example.com',
    sampleRate: 0.1,  // Sample 10% of users
    batchSize: 20
});
```

**Mobile-Side RUM (Swift)**

```swift
// RUMCollector.swift
import Foundation

class RUMCollector {
    static let shared = RUMCollector()
    private var buffer: [[String: Any]] = []
    private let batchSize = 20
    private let flushInterval: TimeInterval = 5
    private let apiUrl = "https://api.example.com/rum"

    private init() {
        Timer.scheduledTimer(withTimeInterval: flushInterval, repeats: true) { _ in
            self.flush()
        }
    }

    func recordRequest(_ request: URLRequest, response: HTTPURLResponse?, duration: TimeInterval, error: Error?) {
        var data: [String: Any] = [
            "url": request.url?.absoluteString ?? ",
            "method": request.httpMethod ?? "GET",
            "duration": duration,
            "timestamp": ISO8601DateFormatter().string(from: Date()),
            "app_version": Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "",
            "os_version": UIDevice.current.systemVersion,
            "device": UIDevice.current.model
        ]

        if let response = response {
            data["status"] = response.statusCode
            data["success"] = (200...299).contains(response.statusCode)
        }

        if let error = error {
            data["error"] = error.localizedDescription
            data["success"] = false
        }

        buffer.append(data)

        if buffer.count >= batchSize {
            flush()
        }
    }

    private func flush() {
        guard !buffer.isEmpty else { return }

        let batch = buffer
        buffer.removeAll()

        guard let jsonData = try? JSONSerialization.data(withJSONObject: batch) else { return }

        var request = URLRequest(url: URL(string: apiUrl)!)
        request.httpMethod = "POST"
        request.httpBody = jsonData
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        URLSession.shared.dataTask(with: request).resume()
    }
}

// Usage: Swizzle URLSession to automatically capture requests
