**Backend RUM Processor**

```python
# rum_processor.py
from flask import Flask, request, jsonify
import time
from collections import defaultdict
from datetime import datetime, timedelta
import statistics

app = Flask(__name__)

# In-memory storage (use Redis/DB in production)
rum_data = []

@app.route('/rum', methods=['POST'])
def collect_rum():
    """Collect RUM data from clients"""
    data = request.get_json()

    if isinstance(data, list):
        for item in data:
            item['received_at'] = time.time()
            rum_data.append(item)
    else:
        data['received_at'] = time.time()
        rum_data.append(data)

    # Limit storage (keep last 100k events)
    if len(rum_data) > 100000:
        rum_data[:] = rum_data[-100000:]

    return '', 204

@app.route('/rum/dashboard')
def rum_dashboard():
    """Generate RUM metrics"""
    # Filter last hour
    cutoff = time.time() - 3600
    recent = [d for d in rum_data if d.get('received_at', 0) > cutoff]

    if not recent:
        return jsonify({'message': 'No recent data'})

    # Group by endpoint
    endpoints = defaultdict(list)
    for r in recent:
        url = r.get('url', '')
        endpoints[url].append(r)

    # Calculate metrics
    metrics = {
        'total_requests': len(recent),
        'error_rate': sum(1 for r in recent if not r.get('success', True)) / len(recent),
        'avg_duration': statistics.mean(r['duration'] for r in recent),
        'p95_duration': sorted(r['duration'] for r in recent)[int(len(recent) * 0.95)],
        'by_endpoint': {}
    }

    for url, requests in endpoints.items():
        durations = [r['duration'] for r in requests]
        metrics['by_endpoint'][url] = {
            'count': len(requests),
            'avg_duration': statistics.mean(durations),
            'p95_duration': sorted(durations)[int(len(durations) * 0.95)],
            'error_rate': sum(1 for r in requests if not r.get('success', True)) / len(requests)
        }

    return jsonify(metrics)
