**Schema Diff Testing (Backward Compatibility)**

```javascript
// schema-compatibility.test.js
const { diff } = require('graphql-schema-diff');
const fs = require('fs');

const oldSchema = fs.readFileSync('schema-v1.graphql', 'utf8');
const newSchema = fs.readFileSync('schema-v2.graphql', 'utf8');

describe('Schema Evolution', () => {
  test('should be backward compatible', async () => {
    const result = await diff(oldSchema, newSchema);

    // Check for breaking changes
    const breakingChanges = result.filter(change => change.criticality.level === 'BREAKING');
    expect(breakingChanges).toHaveLength(0);

    // Log non-breaking changes for awareness
    const nonBreaking = result.filter(change => change.criticality.level !== 'BREAKING');
    if (nonBreaking.length > 0) {
      console.log('Non-breaking changes:', nonBreaking);
    }
  });

  test('should not remove deprecated fields too quickly', () => {
    // Ensure deprecated fields exist for at least 2 versions
    // This is a custom rule for your API
  });
});
