        expect(value.data.userUpdated.id).toBe(expectedId);
        received.push(expectedId);
      };

      Promise.all([
        listen(sub1, '1'),
        listen(sub2, '2'),
        listen(sub3, '3')
      ]).then(() => {
        expect(received.sort()).toEqual(['1', '2', '3']);
        done();
      });

      // Trigger events
      pubsub.publish('USER_UPDATED', { userUpdated: { id: '1', name: 'User 1' } });
      pubsub.publish('USER_UPDATED', { userUpdated: { id: '2', name: 'User 2' } });
      pubsub.publish('USER_UPDATED', { userUpdated: { id: '3', name: 'User 3' } });
    });
