describe('GraphQL Rate Limiting', () => {
  test('should rate limit by IP', async () => {
    const client = createTestClient({ ip: '1.2.3.4' });

    // Send many requests quickly
    const requests = Array(100).fill().map(() => 
      client.query('{ user(id: 1) { name } }')
    );

    const results = await Promise.all(requests);

    // Some should be rate limited
    const rateLimited = results.filter(r => r.errors && r.errors[0].message.includes('rate limit'));
    expect(rateLimited.length).toBeGreaterThan(0);
  });

  test('should rate limit by API key', async () => {
    const client1 = createTestClient({ apiKey: 'key1' });
    const client2 = createTestClient({ apiKey: 'key2' });

    // Both clients should have separate rate limits
    const results1 = await Promise.all(
      Array(60).fill().map(() => client1.query('{ user(id: 1) { name } }'))
    );

    const results2 = await Promise.all(
      Array(60).fill().map(() => client2.query('{ user(id: 1) { name } }'))
    );

    const rateLimited1 = results1.filter(r => r.errors && r.errors[0].message.includes('rate limit'));
    const rateLimited2 = results2.filter(r => r.errors && r.errors[0].message.includes('rate limit'));

    // Both should hit their limits independently
    expect(rateLimited1.length).toBeGreaterThan(0);
    expect(rateLimited2.length).toBeGreaterThan(0);
  });

  test('should have different limits for different query costs', async () => {
    const client = createTestClient();

    // Cheap queries should have higher rate limit
    const cheapResults = await Promise.all(
      Array(100).fill().map(() => client.query('{ user(id: 1) { name } }'))
    );

    // Expensive queries should have lower rate limit
    const expensiveResults = await Promise.all(
      Array(20).fill().map(() => client.query(`
        query {
          users {
            posts {
              comments {
                text
              }
            }
          }
        }
      `))
    );

    const cheapLimited = cheapResults.filter(r => r.errors && r.errors[0].message.includes('rate limit'));
    const expensiveLimited = expensiveResults.filter(r => r.errors && r.errors[0].message.includes('rate limit'));

    // Expensive queries should hit limits sooner
    expect(expensiveLimited.length).toBeGreaterThan(cheapLimited.length);
  });
});
