**Authorization Testing**

```javascript
// authorization.test.js
describe('GraphQL Authorization', () => {
  const queries = {
    public: '{ publicData }',
    user: '{ userData }',
    admin: '{ adminData }',
  };

  const users = {
    guest: { role: 'GUEST' },
    user: { role: 'USER', id: '123' },
    admin: { role: 'ADMIN', id: '456' },
    otherUser: { role: 'USER', id: '789' },
  };

  test('should enforce field-level authorization', async () => {
    // Guest can only access public data
    let result = await executeAs(users.guest, queries.public);
    expect(result.errors).toBeUndefined();

    result = await executeAs(users.guest, queries.user);
    expect(result.errors).toBeDefined();

    result = await executeAs(users.guest, queries.admin);
    expect(result.errors).toBeDefined();

    // User can access user data but not admin data
    result = await executeAs(users.user, queries.user);
    expect(result.errors).toBeUndefined();

    result = await executeAs(users.user, queries.admin);
    expect(result.errors).toBeDefined();

    // Admin can access everything
    result = await executeAs(users.admin, queries.admin);
    expect(result.errors).toBeUndefined();
  });

  test('should enforce row-level authorization', async () => {
    const query = `
      query GetUser($id: ID!) {
        user(id: $id) {
          id
          email
          ssn
        }
      }
    `;

    // User can see their own data
    const selfResult = await executeAs(users.user, query, { id: '123' });
    expect(selfResult.errors).toBeUndefined();
    expect(selfResult.data.user.email).toBeDefined();

    // User cannot see another user's data
    const otherResult = await executeAs(users.user, query, { id: '789' });
    expect(otherResult.errors).toBeDefined();

    // Admin can see anyone's data
    const adminResult = await executeAs(users.admin, query, { id: '789' });
    expect(adminResult.errors).toBeUndefined();
  });

  test('should not leak existence through errors', async () => {
    const query = `
      query GetUser($id: ID!) {
        user(id: $id) {
          name
        }
      }
    `;

    // Request for non-existent user should return null, not error
    const nonExistentResult = await executeAs(users.user, query, { id: 'non-existent' });
    expect(nonExistentResult.errors).toBeUndefined();
    expect(nonExistentResult.data.user).toBeNull();

    // Request for existing user returns data
    const existingResult = await executeAs(users.user, query, { id: '123' });
    expect(existingResult.errors).toBeUndefined();
    expect(existingResult.data.user).not.toBeNull();

    // Attacker cannot distinguish between "no permission" and "doesn't exist"
    const noPermissionResult = await executeAs(users.user, query, { id: '789' });
    expect(noPermissionResult.data.user).toBeNull();
    // Should be indistinguishable from non-existent
  });
});
```

**Batch Attack Testing**

```javascript
// batch-attack.test.js
describe('Batch Attack Prevention', () => {
  test('should limit batch size', async () => {
    const batch = [];
    for (let i = 0; i < 1000; i++) {
      batch.push({ query: '{ user(id: 1) { name } }' });
    }

    const response = await fetch('/graphql', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(batch)
    });

    expect(response.status).toBe(413); // Payload Too Large
  });

  test('should limit concurrent batch processing', async () => {
    const start = Date.now();

    // Send 10 batches of 10 queries each
    const batches = Array(10).fill().map(() => {
      const batch = Array(10).fill().map(() => ({
        query: '{ expensiveOperation }'
      }));
      return fetch('/graphql', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(batch)
      });
    });

    await Promise.all(batches);
    const duration = Date.now() - start;

    // Should process batches sequentially or with limited concurrency
    // 10 batches * 10 queries * 100ms each = 10s if serial
    // Should be less than that if properly limited
    expect(duration).toBeLessThan(5000);
  });
});
```

**Key Insight:** GraphQL security requires defense in depth. Introspection should be disabled in production. Queries should be limited by depth, complexity, and rate. Authorization must be enforced at field and row levels. And all of this must be tested—attackers will find the gaps in your defenses.

