**Testing Proto Compilation**

```javascript
// proto-compile.test.js
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

describe('Protocol Buffer Compilation', () => {
  const protoDir = path.join(__dirname, '../proto');
  const outputDir = path.join(__dirname, '../generated');

  beforeAll(() => {
    // Clean output directory
    if (fs.existsSync(outputDir)) {
      fs.rmSync(outputDir, { recursive: true, force: true });
    }
    fs.mkdirSync(outputDir);
  });

  test('should compile all proto files without errors', (done) => {
    const command = `protoc \
      --proto_path=${protoDir} \
      --python_out=${outputDir} \
      --grpc_python_out=${outputDir} \
      ${protoDir}/*.proto`;

    exec(command, (error, stdout, stderr) => {
      expect(error).toBeNull();
      expect(stderr).toBe('');
      done();
    });
  });

  test('should generate expected files', () => {
    const files = fs.readdirSync(outputDir);
    expect(files).toContain('user_pb2.py');
    expect(files).toContain('user_pb2_grpc.py');
  });

  test('generated files should be importable', () => {
    expect(() => {
      require(path.join(outputDir, 'user_pb2'));
    }).not.toThrow();
  });
});
