# test_oneof.py
class TestPaymentOneOf(unittest.TestCase):
    def test_only_one_field_set(self):
        payment = payment_pb2.Payment()
        payment.credit_card = "4111-1111-1111-1111"
        payment.amount = 100.0

        # Verify which field is set
        self.assertEqual(payment.WhichOneof('method'), 'credit_card')

        # Setting another field should clear the first
        payment.paypal_email = "user@example.com"
        self.assertEqual(payment.WhichOneof('method'), 'paypal_email')
        self.assertEqual(payment.credit_card, "")  # Cleared

    def test_serialization_preserves_oneof(self):
