        payment.bank_account = "123-456-789"
        payment.amount = 200.0

        data = payment.SerializeToString()
        new_payment = payment_pb2.Payment()
        new_payment.ParseFromString(data)

        self.assertEqual(new_payment.WhichOneof('method'), 'bank_account')
        self.assertEqual(new_payment.bank_account, "123-456-789")
