class TestComplexFields(unittest.TestCase):
    def test_map_field(self):
        msg = complex_pb2.ComplexMessage()
        msg.metadata["key1"] = "value1"
        msg.metadata["key2"] = "value2"

        self.assertEqual(len(msg.metadata), 2)
        self.assertEqual(msg.metadata["key1"], "value1")

        # Serialize and verify
        data = msg.SerializeToString()
        new_msg = complex_pb2.ComplexMessage()
        new_msg.ParseFromString(data)

        self.assertEqual(new_msg.metadata["key1"], "value1")

    def test_repeated_field(self):
        msg = complex_pb2.ComplexMessage()
        msg.scores.extend([95, 87, 92])

        self.assertEqual(len(msg.scores), 3)
        self.assertEqual(list(msg.scores), [95, 87, 92])

    def test_repeated_messages(self):
        msg = complex_pb2.ComplexMessage()
        user1 = msg.users.add()
        user1.id = "1"
        user1.name = "User 1"

        user2 = msg.users.add()
        user2.id = "2"
        user2.name = "User 2"

        self.assertEqual(len(msg.users), 2)
        self.assertEqual(msg.users[0].name, "User 1")
```

**Key Insight:** Protocol buffer testing ensures that your data contracts are correct and that serialization works as expected. These tests are cheap to run and catch many issues before they reach the service layer. Test your protos thoroughly—they're the foundation of everything else.

Comprehensive strategies for testing request-response gRPC methods.

**Setting Up a Test Server**

```python
# test_unary.py
import unittest
import grpc
from concurrent import futures

import user_pb2
import user_pb2_grpc

class MockUserService(user_pb2_grpc.UserServiceServicer):
    def __init__(self):
        self.users = {
            "1": user_pb2.User(id="1", name="Alice", email="alice@example.com", age=30),
            "2": user_pb2.User(id="2", name="Bob", email="bob@example.com", age=25),
        }

    def GetUser(self, request, context):
        if request.id in self.users:
            return self.users[request.id]
        else:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            context.set_details(f"User {request.id} not found")
            return user_pb2.User()

    def ListUsers(self, request, context):
        users = list(self.users.values())
        return user_pb2.ListUsersResponse(
            users=users,
            total_count=len(users)
        )

    def CreateUser(self, request, context):
        # Simulate ID generation
        new_id = str(len(self.users) + 1)
        new_user = user_pb2.User(
            id=new_id,
            name=request.name,
            email=request.email,
            age=request.age,
            tags=request.tags
        )
        self.users[new_id] = new_user
        return new_user

class TestUnaryRPCs(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Start server
