```javascript
// handshake.test.js
const WebSocket = require('ws');
const http = require('http');

describe('WebSocket Handshake', () => {
  let server;
  let wsServer;

  beforeEach((done) => {
    server = http.createServer();
    wsServer = new WebSocket.Server({ server });

    wsServer.on('connection', (ws, req) => {
      ws.connectionMetadata = {
        headers: req.headers,
        url: req.url
      };
    });

    server.listen(0, done);
  });

  afterEach((done) => {
    wsServer.close();
    server.close(done);
  });

  test('should successfully upgrade connection', (done) => {
    const port = server.address().port;
    const ws = new WebSocket(`ws://localhost:${port}`);

    ws.on('open', () => {
      expect(ws.readyState).toBe(WebSocket.OPEN);
      ws.close();
      done();
    });

    ws.on('error', (err) => {
      done(err);
    });
  });

  test('should include correct upgrade headers', (done) => {
    const port = server.address().port;
    const ws = new WebSocket(`ws://localhost:${port}`);

    ws.on('open', () => {
      // The server can access the upgrade headers
      const connections = Array.from(wsServer.clients);
      const connection = connections[0];

      expect(connection.connectionMetadata.headers.upgrade).toBe('websocket');
      expect(connection.connectionMetadata.headers.connection).toMatch(/upgrade/i);
      expect(connection.connectionMetadata.headers['sec-websocket-version']).toBe('13');

      ws.close();
      done();
    });
  });
});
