describe('Reconnection', () => {
  let reconnectAttempts = 0;

  function createReconnectingClient(url, options = {}) {
    const ws = new WebSocket(url);

    ws.on('close', () => {
      reconnectAttempts++;
      if (reconnectAttempts < 3) {
        setTimeout(() => {
          createReconnectingClient(url, options);
        }, options.reconnectDelay || 1000);
      }
    });

    return ws;
  }

  test('should reconnect on disconnection', (done) => {
    const ws = createReconnectingClient(`ws://localhost:${port}`, {
      reconnectDelay: 100
    });

    let connectionCount = 0;

    ws.on('open', () => {
      connectionCount++;

      if (connectionCount === 1) {
        // Force disconnect
        ws._socket.destroy();
      } else if (connectionCount === 2) {
        expect(reconnectAttempts).toBe(1);
        done();
      }
    });
  });

  test('should back off exponentially', (done) => {
    const delays = [];
    const startTime = Date.now();

    function connectWithBackoff(attempt) {
      const ws = new WebSocket(`ws://localhost:${port}`);

      ws.on('open', () => {
        ws.close();
      });

      ws.on('close', () => {
        if (attempt < 3) {
          const delay = Math.min(1000 * Math.pow(2, attempt), 30000);
          delays.push(delay);

          setTimeout(() => {
            connectWithBackoff(attempt + 1);
          }, delay);
        } else {
          // Verify delays increased exponentially
          expect(delays[0]).toBeLessThan(delays[1]);
          expect(delays[1]).toBeLessThan(delays[2]);
          done();
        }
      });
    }

    connectWithBackoff(0);
  });
});
