**Room Management Implementation**

```javascript
// room-server.js
class RoomManager {
  constructor() {
    this.rooms = new Map(); // roomName -> Set of clients
  }

  join(ws, roomName) {
    if (!this.rooms.has(roomName)) {
      this.rooms.set(roomName, new Set());
    }
    this.rooms.get(roomName).add(ws);
    ws.rooms = ws.rooms || new Set();
    ws.rooms.add(roomName);
  }

  leave(ws, roomName) {
    const room = this.rooms.get(roomName);
    if (room) {
      room.delete(ws);
      if (room.size === 0) {
        this.rooms.delete(roomName);
      }
    }
    ws.rooms?.delete(roomName);
  }

  broadcast(roomName, message, sender = null) {
    const room = this.rooms.get(roomName);
    if (!room) return;

    room.forEach(client => {
      if (client !== sender && client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    });
  }

  getRoomSize(roomName) {
    return this.rooms.get(roomName)?.size || 0;
  }
}
```

