// room.test.js
describe('Room Management', () => {
  let server;
  let wsServer;
  let roomManager;
  let port;

  beforeEach((done) => {
    server = require('http').createServer();
    wsServer = new WebSocket.Server({ server });
    roomManager = new RoomManager();

    wsServer.on('connection', (ws) => {
      ws.on('message', (data) => {
        const msg = JSON.parse(data.toString());

        switch (msg.type) {
          case 'join':
            roomManager.join(ws, msg.room);
            ws.send(JSON.stringify({ type: 'joined', room: msg.room }));
            break;
          case 'leave':
            roomManager.leave(ws, msg.room);
            ws.send(JSON.stringify({ type: 'left', room: msg.room }));
            break;
          case 'message':
            roomManager.broadcast(msg.room, data, ws);
            break;
        }
      });

      ws.on('close', () => {
        // Remove from all rooms
        if (ws.rooms) {
          ws.rooms.forEach(room => roomManager.leave(ws, room));
        }
      });
    });

    server.listen(0, () => {
      port = server.address().port;
      done();
    });
  });

  afterEach((done) => {
    wsServer.close();
    server.close(done);
  });

