describe('Room Broadcasts', () => {
  test('message should broadcast to room members', (done) => {
    const clients = [];
    const roomMessages = [];

    // Create room owner
    const owner = new WebSocket(`ws://localhost:${port}`);
    clients.push(owner);

    owner.on('open', () => {
      owner.send(JSON.stringify({ type: 'join', room: 'test' }));
    });

    owner.on('message', (data) => {
      const response = JSON.parse(data.toString());
      if (response.type === 'joined') {
        // Create two more members
        for (let i = 0; i < 2; i++) {
          const member = new WebSocket(`ws://localhost:${port}`);
          clients.push(member);

          member.on('open', () => {
            member.send(JSON.stringify({ type: 'join', room: 'test' }));
          });

          member.on('message', (data) => {
            const msg = JSON.parse(data.toString());
            if (msg.type === 'message') {
              roomMessages.push(member);
            }
          });
        }

        // Wait for all to join then send message
        setTimeout(() => {
          owner.send(JSON.stringify({
            type: 'message',
            room: 'test',
            text: 'Hello room!'
          }));
        }, 200);
      }
    });

    // Check after 500ms that both members received message
    setTimeout(() => {
      expect(roomMessages.length).toBe(2);
      done();
    }, 500);
  });

  test('non-members should not receive room messages', (done) => {
    const member = new WebSocket(`ws://localhost:${port}`);
    const nonMember = new WebSocket(`ws://localhost:${port}`);
    let memberMessage = false;
    let nonMemberMessage = false;

    member.on('open', () => {
      member.send(JSON.stringify({ type: 'join', room: 'private' }));
    });

    nonMember.on('open', () => {
      // Don't join any room
    });

    member.on('message', (data) => {
      const msg = JSON.parse(data.toString());
      if (msg.type === 'message') {
        memberMessage = true;
      }
    });

    nonMember.on('message', (data) => {
      const msg = JSON.parse(data.toString());
      if (msg.type === 'message') {
        nonMemberMessage = true;
      }
    });

    // Wait for join, then broadcast
    setTimeout(() => {
      member.send(JSON.stringify({
        type: 'message',
        room: 'private',
        text: 'Secret message'
      }));
    }, 200);

    // Check results
    setTimeout(() => {
      expect(memberMessage).toBe(true);
      expect(nonMemberMessage).toBe(false);
      done();
    }, 500);
  });
});
