**Connection Rate Testing**

```javascript
// connection-rate-test.js
const WebSocket = require('ws');

async function testConnectionRate(url, targetRate, duration) {
  const connections = [];
  const startTime = Date.now();
  let connectionsMade = 0;
  let errors = 0;

  console.log(`Testing connection rate: ${targetRate}/s for ${duration}s`);

  const interval = setInterval(async () => {
    for (let i = 0; i < targetRate; i++) {
      try {
        const ws = new WebSocket(url);

        ws.on('open', () => {
          connectionsMade++;
          connections.push(ws);
        });

        ws.on('error', () => {
          errors++;
        });
      } catch (err) {
        errors++;
      }
    }
  }, 1000);

  await new Promise(resolve => setTimeout(resolve, duration * 1000));
  clearInterval(interval);

  const actualRate = connectionsMade / duration;
  console.log(`Results:`);
  console.log(`  Target rate: ${targetRate}/s`);
  console.log(`  Actual rate: ${actualRate.toFixed(1)}/s`);
  console.log(`  Success: ${connectionsMade}`);
  console.log(`  Errors: ${errors}`);
  console.log(`  Success rate: ${(connectionsMade/(connectionsMade+errors)*100).toFixed(1)}%`);

  // Cleanup
  connections.forEach(ws => ws.close());

  return { connectionsMade, errors, actualRate };
}

// Run test
testConnectionRate('ws://localhost:8080', 100, 10);
```

