// concurrent-connections.js
async function testMaxConcurrentConnections(url, maxConnections) {
  const connections = [];
  const startTime = Date.now();

  console.log(`Testing maximum concurrent connections...`);
  console.log(`Target: ${maxConnections}`);

  for (let i = 0; i < maxConnections; i++) {
    try {
      const ws = new WebSocket(url);

      await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
          reject(new Error('Connection timeout'));
        }, 5000);

        ws.onopen = () => {
          clearTimeout(timeout);
          connections.push(ws);
          resolve();
        };

        ws.onerror = (err) => {
          clearTimeout(timeout);
          reject(err);
        };
      });

      if (i % 100 === 0) {
        console.log(`  ${i} connections established...`);
      }
    } catch (err) {
      console.log(`\nFailed at ${i} connections:`, err.message);
      console.log(`Maximum concurrent connections: ${connections.length}`);
      break;
    }
  }

  const duration = (Date.now() - startTime) / 1000;
  console.log(`\nEstablished ${connections.length} connections in ${duration.toFixed(1)}s`);
  console.log(`Connection rate: ${(connections.length/duration).toFixed(1)}/s`);

  // Test message delivery
  if (connections.length > 0) {
    console.log(`\nTesting message broadcast...`);

    let received = 0;
    connections.forEach(ws => {
      ws.onmessage = () => received++;
    });

    // Send test message
    connections[0].send(JSON.stringify({ type: 'broadcast', test: true }));

    await new Promise(resolve => setTimeout(resolve, 2000));
    console.log(`Received on ${received}/${connections.length} connections`);
  }

  // Cleanup
  connections.forEach(ws => ws.close());
}

