**Memory Leak Testing**

```javascript
// memory-leak-test.js
async function testMemoryLeaks(url, iterations) {
  console.log('Testing for memory leaks...');

  const memorySnapshots = [];

  for (let i = 0; i < iterations; i++) {
    // Create and destroy connections
    const connections = [];

    for (let j = 0; j < 100; j++) {
      const ws = new WebSocket(url);
      connections.push(ws);
    }

    await new Promise(resolve => setTimeout(resolve, 1000));

    connections.forEach(ws => ws.close());

    // Force garbage collection if available
    if (global.gc) {
      global.gc();
    }

    // Take memory snapshot
    const memory = process.memoryUsage();
    memorySnapshots.push(memory.heapUsed);

    console.log(`Iteration ${i+1}: ${(memory.heapUsed / 1024 / 1024).toFixed(2)} MB`);
  }

  // Analyze trend
  const initial = memorySnapshots[0];
  const final = memorySnapshots[memorySnapshots.length - 1];
  const growth = (final - initial) / initial * 100;

  console.log(`\nMemory analysis:`);
  console.log(`  Initial: ${(initial/1024/1024).toFixed(2)} MB`);
  console.log(`  Final: ${(final/1024/1024).toFixed(2)} MB`);
  console.log(`  Growth: ${growth.toFixed(1)}%`);

  if (growth > 10) {
    console.log('⚠️ Possible memory leak detected');
  } else {
    console.log('✅ No significant memory leak');
  }
}

// Run with --expose-gc flag
// node --expose-gc memory-leak-test.js
testMemoryLeaks('ws://localhost:8080', 10);
```

**Key Insight:** WebSocket performance testing requires measuring different metrics than HTTP: connection rate, concurrent connections, message throughput, and memory usage. Each metric stresses different parts of your system. Test them all to ensure your WebSocket service can handle real-world loads.

