**Testing Exactly-Once Semantics**

```java
@Test
void testExactlyOnceSemantics() throws Exception {
    String topic = "exactly-once-topic";

    // Configure producer for exactly-once
    Properties producerProps = new Properties();
    producerProps.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());
    producerProps.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, true);
    producerProps.put(ProducerConfig.ACKS_CONFIG, "all");
    producerProps.put(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "test-transaction-1");

    KafkaProducer<String, String> producer = new KafkaProducer<>(producerProps);
    producer.initTransactions();

    // Send messages in transaction
    producer.beginTransaction();
    producer.send(new ProducerRecord<>(topic, "key1", "value1"));
    producer.send(new ProducerRecord<>(topic, "key2", "value2"));
    producer.commitTransaction();

    // Consumer with isolation level read_committed
    Properties consumerProps = new Properties();
    consumerProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());
    consumerProps.put(ConsumerConfig.GROUP_ID_CONFIG, "test-group");
    consumerProps.put(ConsumerConfig.ISOLATION_LEVEL_CONFIG, "read_committed");

    KafkaConsumer<String, String> consumer = new KafkaConsumer<>(consumerProps);
    consumer.subscribe(Collections.singletonList(topic));

    ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(5));
    assertEquals(2, records.count()); // Should see both messages

    producer.close();
    consumer.close();
}
```

