def test_routing_keys(self, rabbitmq_connection):
    conn, channel, _ = rabbitmq_connection

    # Create topic exchange
    exchange_name = 'topic.test'
    channel.exchange_declare(exchange=exchange_name, exchange_type='topic')

    # Create multiple queues with different bindings
    queue_results = {}

    # Queue for all user events
    user_queue = channel.queue_declare(queue='', exclusive=True).method.queue
    channel.queue_bind(exchange=exchange_name, queue=user_queue, routing_key='user.*')
    queue_results['user'] = []

    # Queue for specific user created events
    created_queue = channel.queue_declare(queue='', exclusive=True).method.queue
    channel.queue_bind(exchange=exchange_name, queue=created_queue, routing_key='user.created')
    queue_results['created'] = []

    # Queue for admin events
    admin_queue = channel.queue_declare(queue='', exclusive=True).method.queue
    channel.queue_bind(exchange=exchange_name, queue=admin_queue, routing_key='admin.#')
    queue_results['admin'] = []

    # Setup consumers
    def make_callback(queue_name):
        def callback(ch, method, properties, body):
            queue_results[queue_name].append(json.loads(body))
            ch.basic_ack(delivery_tag=method.delivery_tag)
        return callback

    for name, queue in [('user', user_queue), ('created', created_queue), ('admin', admin_queue)]:
        channel.basic_consume(queue=queue, on_message_callback=make_callback(name))

    # Publish test messages
    messages = [
        ('user.created', {'event': 'user.created'}),
        ('user.updated', {'event': 'user.updated'}),
        ('admin.user.deleted', {'event': 'admin.user.deleted'}),
    ]

    for routing_key, msg in messages:
        channel.basic_publish(
            exchange=exchange_name,
            routing_key=routing_key,
            body=json.dumps(msg)
        )

    # Process messages
    channel.connection.process_data_events(time_limit=1)

    # Verify routing
    assert len(queue_results['user']) == 3  # All user.* messages
    assert len(queue_results['created']) == 1  # Only user.created
    assert len(queue_results['admin']) == 1  # Only admin.user.deleted

    assert queue_results['created'][0]['event'] == 'user.created'
    assert queue_results['admin'][0]['event'] == 'admin.user.deleted'
