# test_filter.py
import requests
import pytest

class TestFilterOperators:
    BASE_URL = "https://services.odata.org/OData/OData.svc"

    def test_filter_equality(self):
        # Test equals operator
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Name eq 'Bread'", "$top": 1}
        )
        assert response.status_code == 200
        data = response.json()
        assert len(data['value']) == 1
        assert data['value'][0]['Name'] == 'Bread'

    def test_filter_not_equals(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Name ne 'Bread'", "$top": 1}
        )
        assert response.status_code == 200
        data = response.json()
        assert data['value'][0]['Name'] != 'Bread'

    def test_filter_greater_than(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Price gt 20" "$orderby": "Price"}
        )
        assert response.status_code == 200
        data = response.json()
        for product in data['value']:
            assert product['Price'] > 20

    def test_filter_less_than(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Price lt 10", "$orderby": "Price"}
        )
        assert response.status_code == 200
        data = response.json()
        for product in data['value']:
            assert product['Price'] < 10

    def test_filter_greater_than_or_equal(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Price ge 20", "$orderby": "Price"}
        )
        assert response.status_code == 200
        data = response.json()
        for product in data['value']:
            assert product['Price'] >= 20

    def test_filter_less_than_or_equal(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Price le 10", "$orderby": "Price"}
        )
        assert response.status_code == 200
        data = response.json()
        for product in data['value']:
            assert product['Price'] <= 10

    def test_filter_and_combination(self):
        response = requests.get(
            f"{self.BASE_URL}/Products",
            params={"$filter": "Price gt 10 and Price lt 20"}
